/* Constantes                                                        */
/* ---------------------------------------------------------------- */

const DAY_NAMES = ["Domingo", "Lunes", "Martes", "Miércoles", "Jueves", "Viernes", "Sábado"];
const DAY_ORDER = [1, 2, 3, 4, 5, 6, 0]; // Lunes..Domingo para mostrar en UI
const SHIFTS = ["Mañana", "Tarde"];
const DEFAULT_SHIFT_LIMITS = { "Mañana": "11:00", "Tarde": "18:00" };
const DEFAULT_CATEGORIES = ["LIMPIEZA", "HELADERA", "PAPELERA", "FREEZER"];
const DEFAULT_LOCATIONS = [{ id: "loc1", name: "Barra" }, { id: "loc2", name: "Depósito" }];
const NO_CATEGORY = "Sin categoría";
const UNITS = [
  { value: "g", label: "Gramos (g)" },
  { value: "ml", label: "Mililitros (ml)" },
  { value: "L", label: "Litros (L)" },
  { value: "unidades", label: "Unidades" },
];

function normalizeUnit(raw) {
  const v = String(raw || "").trim().toLowerCase();
  if (v === "g" || v === "gr" || v === "grs" || v === "gramos") return "g";
  if (v === "ml" || v === "mililitros") return "ml";
  if (v === "l" || v === "lt" || v === "lts" || v === "litros") return "L";
  if (v === "kg" || v === "kilos") return "g"; // kg ya no existe como unidad: se deja en g, revisar manualmente
  return "unidades";
}

function uid(prefix = "id") {
  return prefix + "_" + Math.random().toString(36).slice(2, 9);
}

function todayIndex() {
  return new Date().getDay();
}

function todayStr() {
  const d = new Date();
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

function daysAgoStr(n) {
  const d = new Date();
  d.setDate(d.getDate() - n);
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

function shortDate(dateStr) {
  const [y, m, d] = dateStr.split("-");
  return `${d}/${m}`;
}

function nowHHMM() {
  const d = new Date();
  return String(d.getHours()).padStart(2, "0") + ":" + String(d.getMinutes()).padStart(2, "0");
}

function groupBy(arr, fn) {
  const g = {};
  arr.forEach(x => {
    const k = fn(x) || NO_CATEGORY;
    if (!g[k]) g[k] = [];
    g[k].push(x);
  });
  return g;
}

// Igual que groupBy, pero para cuando cada elemento puede pertenecer a
// VARIAS claves a la vez (ej: un insumo con varias categorías). El elemento
// aparece repetido, una vez dentro de cada grupo al que pertenece.
function groupByMulti(arr, fn) {
  const g = {};
  arr.forEach(x => {
    const keys = fn(x);
    const list = (keys && keys.length ? keys : [NO_CATEGORY]);
    list.forEach(k => {
      if (!g[k]) g[k] = [];
      g[k].push(x);
    });
  });
  return g;
}

// Categorías de un insumo, en formato array. Soporta insumos viejos que
// todavía tengan el campo singular `category` (antes de que existiera el
// soporte para varias categorías por insumo).
function itemCategories(item) {
  if (Array.isArray(item.categories)) return item.categories;
  if (item.category) return [item.category];
  return [];
}

// Stock de un insumo desglosado por ubicación ({ loc1: n, loc2: n }).
// Soporta insumos viejos que todavía tengan el campo singular `currentStock`
// (antes de que existiera el seguimiento por ubicación).
function itemStock(item, locations) {
  const out = {};
  (locations || DEFAULT_LOCATIONS).forEach(loc => {
    out[loc.id] = Number(item.stock ? item.stock[loc.id] : 0) || 0;
  });
  return out;
}

// Stock total de un insumo, sumando todas sus ubicaciones.
function itemTotalStock(item, locations) {
  const s = itemStock(item, locations);
  return Object.values(s).reduce((a, b) => a + b, 0);
}

// Para una fecha puntual, arma la lista de controles (turno+categoría) que
// corresponden según las asignaciones semanales, aplicando las transferencias
// "solo por hoy" (overrides) que haya para esa fecha.
function controlsForDate(assignments, overrides, dayIdx, dateStr) {
  const list = [];
  assignments.forEach(a => {
    if (!a.days.includes(dayIdx)) return;
    (a.categories || []).forEach(cat => {
      const ov = overrides.find(o => o.date === dateStr && o.shift === a.shift && o.category === cat && o.fromEmployeeId === a.employeeId);
      list.push({
        shift: a.shift,
        category: cat,
        originalEmployeeId: a.employeeId,
        employeeId: ov ? ov.toEmployeeId : a.employeeId,
        overridden: !!ov,
        overrideId: ov ? ov.id : null,
      });
    });
  });
  return list;
}

