function stockStatus(current, min) {
  const cur = Number(current) || 0;
  const m = Number(min) || 0;
  if (cur < m) return "low";
  if (m > 0 && cur <= m * 1.1) return "critical";
  return "ok";
}

function Stamp({ status }) {
  if (status === "low") return <span className="stamp low"><AlertTriangle size={12} /> Bajo</span>;
  if (status === "critical") return <span className="stamp critical"><AlertTriangle size={12} /> Crítico</span>;
  return <span className="stamp ok"><CheckCircle2 size={12} /> OK</span>;
}

function StatusChip({ status, overdue }) {
  if (status === "submitted") return <span className="stamp done"><CheckCircle2 size={12} /> Enviado</span>;
  if (status === "draft") return <span className="stamp draft">Guardado</span>;
  if (overdue) return <span className="stamp overdue"><AlertTriangle size={12} /> Vencido</span>;
  return <span className="stamp pending">Pendiente</span>;
}

function ConfirmModal({ title, text, onConfirm, onCancel }) {
  return (
    <div className="modal-backdrop" onClick={onCancel}>
      <div className="modal-card" onClick={e => e.stopPropagation()}>
        <div className="modal-icon"><ClipboardCheck size={22} /></div>
        <div className="modal-title">{title}</div>
        <div className="modal-text">{text}</div>
        <div className="sa-row">
          <button className="sa-btn sa-btn-ghost sa-btn-block" onClick={onCancel}>No</button>
          <button className="sa-btn sa-btn-primary sa-btn-block" onClick={onConfirm}>Sí</button>
        </div>
      </div>
    </div>
  );
}

