/* Login                                                              */
/* ---------------------------------------------------------------- */

function Login({ users, onLogin }) {
  const [name, setName] = useState("");
  const [pin, setPin] = useState("");
  const [err, setErr] = useState("");

  function submit() {
    const n = name.trim().toLowerCase();
    if (!n || !pin.trim()) { setErr("Completá tu nombre y tu PIN."); return; }
    const found = users.find(u => u.name.trim().toLowerCase() === n && String(u.pin) === pin.trim());
    if (!found) { setErr("Nombre o PIN incorrectos. Consultá con el admin."); return; }
    setErr("");
    onLogin(found);
  }

  return (
    <div className="stockapp">
      <GlobalStyles />
      <div className="login-wrap">
        <div style={{ width: "100%", maxWidth: 360 }}>
          <div className="login-logo-wrap"><img src={LOGO_SRC} alt="Ágape" /></div>
          <div className="login-card">
            <div className="login-title">Control de stock</div>
            <div className="login-sub">Ingresá con tu nombre y PIN para ver tus tareas de hoy.</div>
            {err && <div className="login-error">{err}</div>}
            <div className="sa-field">
              <label>Nombre</label>
              <input className="sa-input" value={name} onChange={e => setName(e.target.value)}
                placeholder="Ej: Sofía" onKeyDown={e => e.key === "Enter" && submit()} />
            </div>
            <div className="sa-field">
              <label>PIN</label>
              <input className="sa-input mono" value={pin} type="password" inputMode="numeric"
                onChange={e => setPin(e.target.value)} placeholder="••••"
                onKeyDown={e => e.key === "Enter" && submit()} />
            </div>
            <button className="sa-btn sa-btn-primary sa-btn-block" onClick={submit}>
              Entrar <ChevronRight size={16} />
            </button>
            <div className="fade-note" style={{ marginTop: 14 }}>
              ¿Primera vez acá? Usuario admin inicial: <b>Admin</b> / PIN <b>1234</b> (cambiá el PIN luego desde Empleados).
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

/* ---------------------------------------------------------------- */
/* Pendientes / Alertas + Exportar                                   */
/* ---------------------------------------------------------------- */

function Pendientes({ items, locations }) {
  const low = items.filter(i => itemTotalStock(i, locations) < Number(i.minStock));
  const [groupMode, setGroupMode] = useState("proveedor"); // 'proveedor' | 'categoria'
  const groups = groupMode === "proveedor"
    ? groupBy(low, i => (i.supplier || "").trim() || "Sin proveedor asignado")
    : groupByMulti(low, i => itemCategories(i));
  const groupNames = Object.keys(groups).sort();
  const [copyStatus, setCopyStatus] = useState("");

  function buildText() {
    const label = groupMode === "proveedor" ? "PROVEEDOR" : "CATEGORÍA";
    const lines = [`Lista de compras - ${new Date().toLocaleDateString("es-AR")}`, ""];
    groupNames.forEach(g => {
      lines.push(`${label}: ${g}`);
      groups[g].forEach(i => {
        const total = itemTotalStock(i, locations);
        const falta = Number(i.minStock) - total;
        lines.push(`- ${i.name}: tiene ${total} ${i.unit} (mínimo ${i.minStock} ${i.unit}) → comprar ${falta > 0 ? falta : i.minStock} ${i.unit}`);
      });
      lines.push("");
    });
    return lines.join("\n");
  }

  async function copyList() {
    try {
      await navigator.clipboard.writeText(buildText());
      setCopyStatus("Copiado ✔");
    } catch (e) {
      setCopyStatus("No se pudo copiar, probá descargar el archivo.");
    }
    setTimeout(() => setCopyStatus(""), 2500);
  }

  function downloadList() {
    try {
      const blob = new Blob([buildText()], { type: "text/plain;charset=utf-8" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `lista-compras-${new Date().toISOString().slice(0, 10)}.txt`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    } catch (e) {
      setCopyStatus("No se pudo descargar. Probá copiar el texto.");
      setTimeout(() => setCopyStatus(""), 2500);
    }
  }

  return (
    <div>
      <div className="sa-section-title" style={{ marginBottom: 2 }}>Pendientes de compra</div>
      <div className="fade-note" style={{ marginBottom: 14 }}>La cantidad al lado de cada insumo es el stock actual.</div>

      {low.length > 0 && (
        <div className="pill-wrap" style={{ marginBottom: 14 }}>
          <span className={"pill tiny" + (groupMode === "proveedor" ? " active" : "")} onClick={() => setGroupMode("proveedor")}>Por proveedor</span>
          <span className={"pill tiny" + (groupMode === "categoria" ? " active" : "")} onClick={() => setGroupMode("categoria")}>Por categoría</span>
        </div>
      )}

      {low.length === 0 && (
        <div className="sa-card sa-empty">
          <CheckCircle2 size={30} color="#2F7A5F" />
          <div style={{ fontWeight: 600 }}>Todo en orden</div>
          <div className="fade-note">Ningún insumo está por debajo de su mínimo.</div>
        </div>
      )}

      {low.length > 0 && (
        <div className="sa-row" style={{ marginBottom: 14 }}>
          <button className="sa-btn sa-btn-ghost sa-btn-block" onClick={copyList}><Copy size={15} /> Copiar lista</button>
          <button className="sa-btn sa-btn-dark sa-btn-block" onClick={downloadList}><Download size={15} /> Descargar .txt</button>
        </div>
      )}
      {copyStatus && <div className="fade-note" style={{ marginBottom: 10 }}>{copyStatus}</div>}

      {groupNames.map(g => (
        <div className="sa-card group-block" key={g}>
          <div className="group-head">{groupMode === "proveedor" ? <Store size={16} /> : <Tag size={16} />} {g}</div>
          {groups[g].map(i => (
            <div className="sa-list-item" key={i.id}>
              <div className="sa-item-name">
                {i.name}
                {groupMode === "proveedor" && itemCategories(i).map(c => <span key={c} className="cat-tag" style={{ marginLeft: 6 }}>{c}</span>)}
                {groupMode === "categoria" && (i.supplier || "").trim() && <span className="cat-tag" style={{ marginLeft: 6 }}>{i.supplier}</span>}
              </div>
              <span className="control-meta mono">
                {itemTotalStock(i, locations)} {i.unit}
                <span style={{ opacity: 0.6, marginLeft: 4 }}>
                  ({locations.map(l => `${l.name} ${itemStock(i, locations)[l.id]}`).join(" · ")})
                </span>
              </span>
            </div>
          ))}
        </div>
      ))}
    </div>
  );
}

/* ---------------------------------------------------------------- */
/* Categorías                                                        */
/* ---------------------------------------------------------------- */

function CategoriesEditor({ categories, setCategories, items, setItems }) {
  const [newCat, setNewCat] = useState("");
  const [pendingDelete, setPendingDelete] = useState(null);
  const [blockedMsg, setBlockedMsg] = useState("");

  function addCat() {
    const v = newCat.trim().toUpperCase();
    if (!v || categories.includes(v)) { setNewCat(""); return; }
    setCategories(freshCats => freshCats.includes(v) ? freshCats : [...freshCats, v]);
    setNewCat("");
  }

  async function askRemove(cat) {
    // Importante: no confiamos en el `items` local (puede estar desactualizado
    // si otro celular cargó insumos con esta categoría hace poco). Releemos la
    // base para no dejar borrar una categoría que en realidad sigue en uso.
    let freshItems = items;
    try {
      const r = await window.storage.get("test-app:items", true);
      freshItems = r ? JSON.parse(r.value) : [];
    } catch (e) {
      setBlockedMsg("No se pudo verificar si hay insumos usando esta categoría (revisá tu conexión). Probá de nuevo.");
      return;
    }
    const count = freshItems.filter(i => itemCategories(i).includes(cat)).length;
    if (count > 0) {
      setBlockedMsg(`No se puede eliminar "${cat}": tiene ${count} insumo${count > 1 ? "s" : ""} asociado${count > 1 ? "s" : ""}. Cambiá o borrá esos insumos primero.`);
      return;
    }
    setBlockedMsg("");
    setPendingDelete(cat);
  }

  function confirmRemove() {
    setCategories(freshCats => freshCats.filter(c => c !== pendingDelete));
    // También sacamos la categoría eliminada de cualquier insumo que ya no
    // debería tenerla asociada (por consistencia, aunque a esta altura ya
    // confirmamos que ningún insumo la usa).
    setPendingDelete(null);
  }

  return (
    <div className="sa-card">
      <div className="sa-item-sub" style={{ marginBottom: 8, fontWeight: 600 }}><Tag size={13} style={{ verticalAlign: -2 }} /> Categorías de insumos</div>
      {blockedMsg && <div className="sa-error">{blockedMsg}</div>}
      <div className="pill-wrap" style={{ marginBottom: 12 }}>
        {categories.map(c => (
          <span className="pill tiny active" key={c}>
            {c}
            <span className="pill-x" onClick={() => askRemove(c)}><X size={12} /></span>
          </span>
        ))}
        {categories.length === 0 && <span className="fade-note">Todavía no creaste categorías.</span>}
      </div>
      <div className="sa-row">
        <input className="sa-input" value={newCat} onChange={e => setNewCat(e.target.value)}
          placeholder="Ej: BARRA" onKeyDown={e => e.key === "Enter" && addCat()} />
        <button className="sa-btn sa-btn-primary" onClick={addCat}><Plus size={15} /> Agregar</button>
      </div>

      {pendingDelete && (
        <ConfirmModal
          title="¿Eliminar categoría?"
          text={`Estás a punto de eliminar "${pendingDelete}". Esta acción no se puede deshacer.`}
          onCancel={() => setPendingDelete(null)}
          onConfirm={confirmRemove}
        />
      )}
    </div>
  );
}

/* ---------------------------------------------------------------- */
/* Ubicaciones (Barra / Depósito, etc.)                               */
