function LocationsEditor({ locations, setLocations }) {
  const [names, setNames] = useState(() => Object.fromEntries(locations.map(l => [l.id, l.name])));
  const [saved, setSaved] = useState(false);

  function setName(id, v) {
    setNames(prev => ({ ...prev, [id]: v }));
    setSaved(false);
  }

  function save() {
    setLocations(fresh => fresh.map(l => ({ ...l, name: (names[l.id] || "").trim() || l.name })));
    setSaved(true);
    setTimeout(() => setSaved(false), 2000);
  }

  return (
    <div className="sa-card">
      <div className="sa-item-sub" style={{ marginBottom: 8, fontWeight: 600 }}><Store size={13} style={{ verticalAlign: -2 }} /> Ubicaciones de stock</div>
      <div className="fade-note" style={{ marginBottom: 12 }}>Cada insumo va a tener un stock independiente en cada una de estas dos ubicaciones, y el total se calcula sumándolas.</div>
      {locations.map(l => (
        <div className="sa-field" key={l.id}>
          <label>Nombre</label>
          <input className="sa-input" value={names[l.id] ?? ""} onChange={e => setName(l.id, e.target.value)} placeholder={l.name} />
        </div>
      ))}
      <button className="sa-btn sa-btn-primary" onClick={save}>Guardar</button>
      {saved && <div className="banner-ok" style={{ marginTop: 10 }}><CheckCircle2 size={16} /> Guardado.</div>}
    </div>
  );
}

