/* ---------------------------------------------------------------- */
/* Grilla semanal (admin)                                             */
/* ---------------------------------------------------------------- */

function buildCategoryGrid(assignments, users) {
  const nameOf = id => users.find(u => u.id === id)?.name || "—";

  const catSet = new Set();
  assignments.forEach(a => (a.categories || []).forEach(c => catSet.add(c)));
  const cats = [...catSet].sort((a, b) => a.localeCompare(b));

  const rows = cats.map(cat => {
    const cells = DAY_ORDER.map(d => {
      const names = new Set();
      assignments.forEach(a => {
        if ((a.categories || []).includes(cat) && a.days.includes(d)) {
          names.add(nameOf(a.employeeId));
        }
      });
      return [...names].sort((a, b) => a.localeCompare(b)).join(", ");
    });
    return { category: cat, cells };
  });

  return { rows };
}

function WeeklyGrid({ assignments, users }) {
  const { rows } = buildCategoryGrid(assignments, users);
  const dayLabels = DAY_ORDER.map(d => DAY_NAMES[d].slice(0, 3));

  function downloadExcel() {
    const header = ["Categoría", ...dayLabels];
    const body = rows.map(r => [r.category, ...r.cells.map(c => c || "—")]);
    const ws = XLSX.utils.aoa_to_sheet([header, ...body]);
    ws["!cols"] = [{ wch: 18 }, ...dayLabels.map(() => ({ wch: 16 }))];
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Turnos");
    XLSX.writeFile(wb, `grilla-turnos-${todayStr()}.xlsx`);
  }

  return (
    <div className="sa-card">
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 10 }}>
        <div className="sa-item-sub" style={{ fontWeight: 600 }}>Grilla semanal</div>
        <button className="sa-btn sa-btn-dark sa-btn-sm" onClick={downloadExcel}><Download size={14} /> Excel</button>
      </div>

      {rows.length === 0 && <div className="fade-note">Todavía no hay asignaciones para mostrar.</div>}

      {rows.length > 0 && (
        <div style={{ overflowX: "auto" }}>
          <table className="grid-table">
            <thead>
              <tr>
                <th>Categoría</th>
                {dayLabels.map(d => <th key={d}>{d}</th>)}
              </tr>
            </thead>
            <tbody>
              {rows.map(r => (
                <tr key={r.category}>
                  <td>{r.category}</td>
                  {r.cells.map((c, idx) => (
                    <td key={idx} className={c ? "grid-cell-filled" : "grid-cell-empty"}>{c || "—"}</td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

/* ---------------------------------------------------------------- */
/* Asignaciones (admin)                                               */
/* ---------------------------------------------------------------- */

function emptyAssignForm() { return { employeeId: "", days: [], shift: "Mañana", categories: [] }; }

function AssignmentsAdmin({ assignments, setAssignments, users, items, categories, shiftLimits, setShiftLimits }) {
  const employees = users.filter(u => u.role === "employee");
  const [adding, setAdding] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState(emptyAssignForm());
  const [error, setError] = useState("");

  function toggleDay(d) {
    setForm(f => ({ ...f, days: f.days.includes(d) ? f.days.filter(x => x !== d) : [...f.days, d] }));
  }
  function toggleCat(c) {
    setForm(f => ({ ...f, categories: f.categories.includes(c) ? f.categories.filter(x => x !== c) : [...f.categories, c] }));
  }

  function startAdd() { setForm(emptyAssignForm()); setAdding(true); setEditingId(null); setError(""); }
  function startEdit(a) { setForm({ employeeId: a.employeeId, days: a.days, shift: a.shift, categories: a.categories || [] }); setEditingId(a.id); setAdding(false); setError(""); }
  function cancel() { setAdding(false); setEditingId(null); setError(""); }

  function findConflict() {
    const nameOf = id => users.find(u => u.id === id)?.name || "—";
    for (const a of assignments) {
      if (a.id === editingId) continue;
      if (a.employeeId === form.employeeId) continue;
      if (a.shift !== form.shift) continue;
      const sharedDays = (a.days || []).filter(d => form.days.includes(d));
      if (sharedDays.length === 0) continue;
      const sharedCats = (a.categories || []).filter(c => form.categories.includes(c));
      if (sharedCats.length === 0) continue;
      const dayLabel = DAY_NAMES[sharedDays[0]];
      return `${sharedCats[0]} los ${dayLabel} en el turno ${form.shift} ya está asignado a ${nameOf(a.employeeId)}.`;
    }
    return null;
  }

  function save() {
    if (!form.employeeId || form.days.length === 0 || form.categories.length === 0) return;
    const conflict = findConflict();
    if (conflict) { setError(conflict); return; }
    setError("");
    if (editingId) {
      setAssignments(assignments.map(a => a.id === editingId ? { ...a, ...form } : a));
    } else {
      setAssignments([...assignments, { id: uid("asg"), ...form }]);
    }
    cancel();
  }
  function remove(id) { setAssignments(assignments.filter(a => a.id !== id)); }

  function itemCountFor(cats) {
    return items.filter(i => itemCategories(i).some(c => cats.includes(c))).length;
  }

  const isEditing = adding || editingId;
  const nameOf = id => users.find(u => u.id === id)?.name || "—";

  const categoriesWithItems = categories.filter(cat => items.some(i => itemCategories(i).includes(cat)));
  const coverageGaps = categoriesWithItems.filter(cat => {
    return !assignments.some(a => (a.categories || []).includes(cat) && a.days.length > 0);
  });

  return (
    <div>
      {coverageGaps.length > 0 && (
        <div className="sa-card" style={{ borderColor: "#E3B8AC" }}>
          <div className="sa-item-sub" style={{ fontWeight: 600, color: "var(--brick)", marginBottom: 6, display: "flex", alignItems: "center", gap: 6 }}>
            <AlertTriangle size={14} /> Hay insumos sin nadie que los controle
          </div>
          {coverageGaps.map(cat => (
            <div key={cat} className="fade-note" style={{ marginBottom: 4 }}>
              <b style={{ color: "var(--ink)" }}>{cat}</b> no tiene ningún control asignado.
            </div>
          ))}
        </div>
      )}

      <ShiftLimitsEditor shiftLimits={shiftLimits} setShiftLimits={setShiftLimits} />
      <WeeklyGrid assignments={assignments} users={users} />

      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
        <div className="sa-section-title" style={{ marginBottom: 0 }}>Asignaciones</div>
        {!isEditing && employees.length > 0 && categories.length > 0 && (
          <button className="sa-btn sa-btn-primary sa-btn-sm" onClick={startAdd}><Plus size={15} /> Nueva</button>
        )}
      </div>

      {employees.length === 0 && <div className="sa-card fade-note">Cargá empleados primero, en la pestaña Empleados.</div>}
      {categories.length === 0 && <div className="sa-card fade-note">Cargá categorías primero, en la pestaña Insumos.</div>}

      {isEditing && (
        <div className="sa-card">
          {error && <div className="sa-error"><AlertTriangle size={13} style={{ verticalAlign: -2, marginRight: 5 }} />{error}</div>}
          <div className="sa-field">
            <label>Empleado</label>
            <div className="pill-wrap">
              {employees.map(e => (
                <span key={e.id} className={"pill" + (form.employeeId === e.id ? " active" : "")} onClick={() => setForm({ ...form, employeeId: e.id })}>{e.name}</span>
              ))}
            </div>
          </div>
          <div className="sa-field">
            <label>Días</label>
            <div className="pill-wrap">
              {DAY_ORDER.map(d => (
                <span key={d} className={"pill" + (form.days.includes(d) ? " active" : "")} onClick={() => toggleDay(d)}>{DAY_NAMES[d].slice(0, 3)}</span>
              ))}
            </div>
          </div>
          <div className="sa-field">
            <label>Turno</label>
            <div className="pill-wrap">
              {SHIFTS.map(s => (
                <span key={s} className={"pill" + (form.shift === s ? " active" : "")} onClick={() => setForm({ ...form, shift: s })}>{s} <span className="fade-note" style={{ color: form.shift === s ? "#D8C7AE" : undefined }}>· hasta {shiftLimits[s] || "—"}</span></span>
              ))}
            </div>
          </div>
          <div className="sa-field">
            <label>Categorías a controlar</label>
            <div className="pill-wrap">
              {categories.map(c => (
                <span key={c} className={"pill tiny" + (form.categories.includes(c) ? " active" : "")} onClick={() => toggleCat(c)}>{c}</span>
              ))}
            </div>
            {form.categories.length > 0 && (
              <div className="fade-note" style={{ marginTop: 6 }}>{itemCountFor(form.categories)} insumo(s) incluidos con esas categorías.</div>
            )}
          </div>
          <div className="sa-row">
            <button className="sa-btn sa-btn-ghost sa-btn-block" onClick={cancel}><X size={15} /> Cancelar</button>
            <button className="sa-btn sa-btn-primary sa-btn-block" onClick={save}><Check size={15} /> Guardar</button>
          </div>
        </div>
      )}

      <div className="sa-card">
        {assignments.length === 0 && (
          <div className="sa-empty">
            <CalendarDays size={28} />
            <div style={{ fontWeight: 600 }}>Sin asignaciones todavía</div>
            <div className="fade-note">Decidí qué categorías controla cada empleado y cuándo.</div>
          </div>
        )}
        {assignments.map(a => (
          <div className="sa-list-item" key={a.id}>
            <div>
              <div className="sa-item-name">{nameOf(a.employeeId)} · {a.shift} <span className="fade-note">hasta {shiftLimits[a.shift] || "—"}</span></div>
              <div className="sa-item-sub">{a.days.slice().sort((x, y) => DAY_ORDER.indexOf(x) - DAY_ORDER.indexOf(y)).map(d => DAY_NAMES[d].slice(0, 3)).join(", ")}</div>
              <div className="sa-item-sub mono">{(a.categories || []).join(", ")} · {itemCountFor(a.categories || [])} insumo(s)</div>
            </div>
            <div style={{ display: "flex", gap: 6 }}>
              <button className="sa-icon-btn outline" onClick={() => startEdit(a)}><Pencil size={15} /></button>
              <button className="sa-icon-btn outline danger" onClick={() => remove(a.id)}><Trash2 size={15} /></button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

/* ---------------------------------------------------------------- */
/* Mi turno (empleado)                                                */
/* ---------------------------------------------------------------- */

function ControlDetail({ control, items, session, submission, onBack, onSave, onSubmit, locations }) {
  const catItems = items.filter(i => itemCategories(i).includes(control.category));
  const initialValues = {};
  if (submission && submission.values) {
    catItems.forEach(it => { if (submission.values[it.id] !== undefined) initialValues[it.id] = submission.values[it.id]; });
  }
  const [values, setValues] = useState(initialValues);
  const [confirming, setConfirming] = useState(false);
  const [flash, setFlash] = useState("");
  const readOnly = submission && submission.status === "submitted";

  function setVal(id, v) { setValues(prev => ({ ...prev, [id]: v })); }

  const completedCount = catItems.filter(it => values[it.id] !== undefined && values[it.id] !== "").length;
  const allComplete = catItems.length > 0 && completedCount === catItems.length;

  function handleSave() {
    onSave(control, values);
    setFlash("Guardado. Podés continuar más tarde.");
    setTimeout(() => setFlash(""), 2500);
  }

  function handleSubmit() {
    onSubmit(control, values);
    setConfirming(false);
  }

  return (
    <div>
      <button className="back-link" onClick={onBack}><ChevronLeft size={16} /> Volver a mis controles</button>

      <div className="sa-card">
        <div className="sa-item-sub" style={{ marginBottom: 4, fontWeight: 600 }}>{control.category} · {control.shift}</div>
        {readOnly ? (
          <div className="fade-note">Ya enviado{submission?.submittedAt ? ` a las ${new Date(submission.submittedAt).toLocaleTimeString("es-AR", { hour: "2-digit", minute: "2-digit" })}` : ""}.</div>
        ) : (
          <>
            <div className="fade-note">{completedCount} / {catItems.length} controlados</div>
            <div className="progress-track">
              <div className="progress-fill" style={{ width: `${catItems.length ? (completedCount / catItems.length) * 100 : 0}%` }} />
            </div>
          </>
        )}

        {flash && <div className="banner-ok" style={{ marginTop: 10 }}><CheckCircle2 size={16} /> {flash}</div>}

        <div style={{ marginTop: 10 }}>
          {catItems.map(it => {
            const v = values[it.id];
            const filled = v !== undefined && v !== "";
            return (
              <div className="checklist-row" key={it.id} style={{ borderBottom: "1px dashed var(--border)" }}>
                <div style={{ flex: 1 }}>
                  <div className="sa-item-name">{it.name}</div>
                  <div className="sa-item-sub mono">mínimo {it.minStock} {it.unit}</div>
                  <div className="sa-item-sub mono">último ({locations[0].name}): {itemStock(it, locations)[locations[0].id] ?? "—"} {it.unit}</div>
                </div>
                <input
                  className={"sa-input mono" + (!filled && !readOnly ? " pending" : "")}
                  style={{ width: 84, textAlign: "center" }}
                  type="number"
                  placeholder="Stock"
                  value={v ?? ""}
                  disabled={readOnly}
                  onChange={e => setVal(it.id, e.target.value)}
                />
                {filled ? <Stamp status={stockStatus(v, it.minStock)} /> : !readOnly && <span className="stamp pending">Falta</span>}
              </div>
            );
          })}
        </div>

        {!readOnly && (
          <div className="sa-row" style={{ marginTop: 14 }}>
            <button className="sa-btn sa-btn-ghost sa-btn-block" onClick={handleSave}>Guardar</button>
            <button className="sa-btn sa-btn-primary sa-btn-block" disabled={!allComplete} onClick={() => setConfirming(true)}>
              {allComplete ? "Enviar" : `Faltan ${catItems.length - completedCount}`}
            </button>
          </div>
        )}
      </div>

      {confirming && (
        <ConfirmModal
          title="¿Enviar control?"
          text="Una vez enviado, el control de esta categoría queda cerrado por hoy."
          onCancel={() => setConfirming(false)}
          onConfirm={handleSubmit}
        />
      )}
    </div>
  );
}

function MyShift({ session, assignments, overrides, items, setItems, locations, addLogBatch, submissions, upsertSubmission, shiftLimits }) {
  const today = todayIndex();
  const date = todayStr();
  const mine = controlsForDate(assignments, overrides, today, date).filter(c => c.employeeId === session.id);

  const controlsMap = {};
  mine.forEach(c => {
    const key = c.shift + "__" + c.category;
    if (!controlsMap[key]) controlsMap[key] = { shift: c.shift, category: c.category };
  });
  const controls = Object.values(controlsMap).map(c => ({
    ...c,
    id: `${date}_${session.id}_${c.shift}_${c.category}`,
  }));

  const [selected, setSelected] = useState(null);

  function getSubmission(id) { return submissions.find(s => s.id === id); }

  function handleSave(control, values) {
    upsertSubmission({
      id: control.id, date, employeeId: session.id, employeeName: session.name,
      shift: control.shift, category: control.category, status: "draft", values, updatedAt: new Date().toISOString(),
    });
  }

  function handleSubmit(control, values) {
    const now = new Date().toISOString();
    const catItems = items.filter(i => itemCategories(i).includes(control.category));
    // El número que carga el empleado durante el turno es el stock de SU
    // ubicación (la primera de la lista). La(s) otra(s) ubicación(es) las
    // sigue cargando el admin manualmente desde la ficha del insumo, y no
    // se tocan acá — así el total sigue sumando ambas.
    const primaryLoc = locations[0].id;
    setItems(freshItems => freshItems.map(it => {
      if (!itemCategories(it).includes(control.category) || values[it.id] === undefined || values[it.id] === "") return it;
      return { ...it, stock: { ...itemStock(it, locations), [primaryLoc]: Number(values[it.id]) }, lastChecked: { by: session.name, at: now } };
    }));
    const batch = catItems.map(it => ({
      itemId: it.id, itemName: it.name, employeeId: session.id, employeeName: session.name,
      value: Number(values[it.id]), min: it.minStock, unit: it.unit, at: now,
    }));
    addLogBatch(batch);
    upsertSubmission({
      id: control.id, date, employeeId: session.id, employeeName: session.name,
      shift: control.shift, category: control.category, status: "submitted", values, updatedAt: now, submittedAt: now,
    });
    setSelected(null);
  }

  if (selected) {
    return (
      <ControlDetail
        control={selected}
        items={items}
        session={session}
        submission={getSubmission(selected.id)}
        onBack={() => setSelected(null)}
        onSave={handleSave}
        onSubmit={handleSubmit}
        locations={locations}
      />
    );
  }

  return (
    <div>
      <div className="sa-section-title">Mi turno de hoy · {DAY_NAMES[today]}</div>

      {controls.length === 0 && (
        <div className="sa-card sa-empty">
          <CalendarDays size={28} />
          <div style={{ fontWeight: 600 }}>No tenés controles asignados hoy</div>
          <div className="fade-note">Consultá con el admin si esperabas tener tareas.</div>
        </div>
      )}

      {controls.length > 0 && (
        <div className="sa-card">
          {controls.map(c => {
            const sub = getSubmission(c.id);
            const status = sub ? sub.status : "pending";
            const overdue = status !== "submitted" && shiftLimits[c.shift] && nowHHMM() > shiftLimits[c.shift];
            return (
              <div className="control-row" key={c.id} onClick={() => setSelected(c)}>
                <div className="control-main">
                  <span className="control-cat">{c.category}</span>
                  <span className="control-meta">{c.shift} · hasta {shiftLimits[c.shift] || "—"}</span>
                </div>
                <StatusChip status={status} overdue={overdue} />
                <ChevronRight size={16} color="#B39B7C" />
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

/* ---------------------------------------------------------------- */
/* Hoy (admin) — controles pendientes y transferencias por un día     */
/* ---------------------------------------------------------------- */

function TodayOverview({ assignments, overrides, upsertOverride, removeOverride, users, submissions, shiftLimits }) {
  const today = todayIndex();
  const date = todayStr();
  const [transferringKey, setTransferringKey] = useState(null);

  const nameOf = id => users.find(u => u.id === id)?.name || "—";
  const raw = controlsForDate(assignments, overrides, today, date);

  // dedupe por shift+categoría (no debería haber duplicados, pero por las dudas)
  const seen = new Set();
  const controls = raw.filter(c => {
    const k = c.shift + "__" + c.category;
    if (seen.has(k)) return false;
    seen.add(k);
    return true;
  });

  const employees = users.filter(u => u.role === "employee");

  function getSubmission(employeeId, shift, category) {
    const id = `${date}_${employeeId}_${shift}_${category}`;
    return submissions.find(s => s.id === id);
  }

  function transferTo(control, toEmployeeId) {
    if (toEmployeeId === control.originalEmployeeId) {
      if (control.overrideId) removeOverride(control.overrideId);
      setTransferringKey(null);
      return;
    }
    upsertOverride({
      id: `${date}_${control.shift}_${control.category}`,
      date, shift: control.shift, category: control.category,
      fromEmployeeId: control.originalEmployeeId, fromEmployeeName: nameOf(control.originalEmployeeId),
      toEmployeeId, toEmployeeName: nameOf(toEmployeeId),
      createdAt: new Date().toISOString(),
    });
    setTransferringKey(null);
  }

  return (
    <div>
      <div className="sa-section-title">Controles de hoy · {DAY_NAMES[today]}</div>

      {controls.length === 0 && (
        <div className="sa-card sa-empty">
          <ListChecks size={28} />
          <div style={{ fontWeight: 600 }}>No hay controles asignados hoy</div>
          <div className="fade-note">Configurá asignaciones en la pestaña Turnos.</div>
        </div>
      )}

      {controls.length > 0 && (
        <div className="sa-card">
          {controls.map(c => {
            const key = c.shift + "__" + c.category;
            const sub = getSubmission(c.employeeId, c.shift, c.category);
            const status = sub ? sub.status : "pending";
            const overdue = status !== "submitted" && shiftLimits[c.shift] && nowHHMM() > shiftLimits[c.shift];
            const isTransferring = transferringKey === key;
            return (
              <div key={key} style={{ borderBottom: "1px dashed var(--border)", padding: "12px 0" }}>
                <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div className="sa-item-name">
                      {c.category}
                      {c.overridden && <span className="cat-tag" style={{ marginLeft: 6 }}>Transferido</span>}
                    </div>
                    <div className="sa-item-sub mono">{nameOf(c.employeeId)} · {c.shift} · hasta {shiftLimits[c.shift] || "—"}</div>
                  </div>
                  <StatusChip status={status} overdue={overdue} />
                  {status !== "submitted" && (
                    <button className="sa-icon-btn outline" title="Transferir por hoy" onClick={() => setTransferringKey(isTransferring ? null : key)}>
                      <ArrowRightLeft size={15} />
                    </button>
                  )}
                </div>

                {isTransferring && (
                  <div style={{ marginTop: 10 }}>
                    <div className="fade-note" style={{ marginBottom: 6 }}>Asignar el control de hoy a:</div>
                    <div className="pill-wrap">
                      {employees.filter(e => e.id !== c.employeeId).map(e => (
                        <span key={e.id} className="pill tiny" onClick={() => transferTo(c, e.id)}>{e.name}</span>
                      ))}
                      {c.overridden && (
                        <span className="pill tiny" onClick={() => transferTo(c, c.originalEmployeeId)}>
                          Revertir a {nameOf(c.originalEmployeeId)}
                        </span>
                      )}
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

/* ---------------------------------------------------------------- */
/* Historial (admin)                                                 */
/* ---------------------------------------------------------------- */

function SubmissionDetail({ submission, items, onBack, locations }) {
  const catItems = items.filter(i => itemCategories(i).includes(submission.category));
  return (
    <div>
      <button className="back-link" onClick={onBack}><ChevronLeft size={16} /> Volver al historial</button>
      <div className="sa-card">
        <div className="sa-item-name" style={{ fontSize: 16 }}>{submission.category}</div>
        <div className="sa-item-sub mono" style={{ marginBottom: 10 }}>
          {submission.employeeName} · {submission.shift} · {new Date(submission.submittedAt).toLocaleDateString("es-AR", { day: "numeric", month: "long" })} · {new Date(submission.submittedAt).toLocaleTimeString("es-AR", { hour: "2-digit", minute: "2-digit" })}
        </div>
        <div className="fade-note" style={{ marginBottom: 8 }}>Valores cargados para {locations[0].name}. El total sumando {locations.slice(1).map(l => l.name).join(", ")} se ve en Insumos.</div>
        {catItems.map(it => {
          const v = submission.values ? submission.values[it.id] : undefined;
          return (
            <div className="sa-list-item" key={it.id}>
              <div className="sa-item-name">{it.name}</div>
              <span className="control-meta mono">{v !== undefined && v !== "" ? `${v} ${it.unit}` : "—"}</span>
            </div>
          );
        })}
        {catItems.length === 0 && <div className="fade-note">Esos insumos ya no existen en el sistema.</div>}
      </div>
    </div>
  );
}

function History({ submissions, items, locations }) {
  const [who, setWho] = useState("Todos");
  const [selected, setSelected] = useState(null);
  const [from, setFrom] = useState(daysAgoStr(6));
  const [to, setTo] = useState(todayStr());
  const [exportMsg, setExportMsg] = useState("");

  const sent = submissions.filter(s => s.status === "submitted");
  const employees = [...new Set(sent.map(s => s.employeeName))];
  const filtered = who === "Todos" ? sent : sent.filter(s => s.employeeName === who);

  const byDay = {};
  filtered.forEach(s => {
    const d = new Date(s.submittedAt).toLocaleDateString("es-AR", { weekday: "long", day: "numeric", month: "long" });
    if (!byDay[d]) byDay[d] = [];
    byDay[d].push(s);
  });
  const dayKeys = Object.keys(byDay);
  dayKeys.forEach(d => byDay[d].sort((a, b) => new Date(b.submittedAt) - new Date(a.submittedAt)));

  function downloadExcel() {
    setExportMsg("");
    if (!from || !to || from > to) { setExportMsg("Revisá el rango de fechas."); return; }
    const inRange = sent.filter(s => s.date >= from && s.date <= to);
    if (inRange.length === 0) { setExportMsg("No hay controles enviados en ese rango."); return; }

    const colKeySet = new Set();
    const cols = [];
    inRange.forEach(s => {
      const key = s.date + "|" + s.employeeName;
      if (!colKeySet.has(key)) { colKeySet.add(key); cols.push({ date: s.date, employeeName: s.employeeName }); }
    });
    cols.sort((a, b) => (a.date + a.employeeName).localeCompare(b.date + b.employeeName));

    const sortedItems = items.slice().sort((a, b) => {
      const catA = itemCategories(a).join(", ") || NO_CATEGORY, catB = itemCategories(b).join(", ") || NO_CATEGORY;
      if (catA !== catB) return catA.localeCompare(catB);
      return a.name.localeCompare(b.name);
    });

    const header = ["Insumo", "Categorías", ...cols.map(c => `${shortDate(c.date)} - ${c.employeeName} (${locations[0].name})`)];
    const rows = sortedItems.map(it => {
      const row = [it.name, itemCategories(it).join(", ") || NO_CATEGORY];
      cols.forEach(c => {
        const match = inRange.find(s => s.date === c.date && s.employeeName === c.employeeName && s.values && s.values[it.id] !== undefined && s.values[it.id] !== "");
        row.push(match ? `${match.values[it.id]} ${it.unit}` : "");
      });
      return row;
    });

    try {
      const ws = XLSX.utils.aoa_to_sheet([header, ...rows]);
      ws["!cols"] = [{ wch: 22 }, { wch: 16 }, ...cols.map(() => ({ wch: 14 }))];
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "Stock");
      XLSX.writeFile(wb, `stock-${from}_a_${to}.xlsx`);
    } catch (e) {
      setExportMsg("No se pudo generar el archivo.");
    }
  }

  if (selected) {
    return <SubmissionDetail submission={selected} items={items} onBack={() => setSelected(null)} locations={locations} />;
  }

  return (
    <div>
      <div className="sa-section-title">Historial de controles</div>

      <div className="sa-card">
        <div className="sa-item-sub" style={{ marginBottom: 8, fontWeight: 600 }}>Exportar a Excel</div>
        <div className="sa-row">
          <div className="sa-field" style={{ marginBottom: 0 }}>
            <label>Desde</label>
            <input className="sa-input mono" type="date" value={from} onChange={e => setFrom(e.target.value)} />
          </div>
          <div className="sa-field" style={{ marginBottom: 0 }}>
            <label>Hasta</label>
            <input className="sa-input mono" type="date" value={to} onChange={e => setTo(e.target.value)} />
          </div>
        </div>
        <button className="sa-btn sa-btn-dark sa-btn-block" style={{ marginTop: 10 }} onClick={downloadExcel}>
          <Download size={15} /> Descargar Excel
        </button>
        {exportMsg && <div className="fade-note" style={{ marginTop: 8 }}>{exportMsg}</div>}
        <div className="fade-note" style={{ marginTop: 8 }}>Filas: insumos con su categoría. Columnas: fecha y persona que controló. En cada celda, el stock que cargó.</div>
      </div>

      {employees.length > 0 && (
        <div className="pill-wrap" style={{ marginBottom: 14 }}>
          <span className={"pill tiny" + (who === "Todos" ? " active" : "")} onClick={() => setWho("Todos")}>Todos</span>
          {employees.map(e => (
            <span key={e} className={"pill tiny" + (who === e ? " active" : "")} onClick={() => setWho(e)}>{e}</span>
          ))}
        </div>
      )}

      {filtered.length === 0 && (
        <div className="sa-card sa-empty">
          <Clock size={28} />
          <div style={{ fontWeight: 600 }}>Todavía no hay registros</div>
          <div className="fade-note">Acá vas a ver qué categoría controló cada empleado y cuándo.</div>
        </div>
      )}

      {dayKeys.map(day => (
        <div key={day}>
          <div className="history-day">{day}</div>
          <div className="sa-card" style={{ paddingTop: 6, paddingBottom: 6 }}>
            {byDay[day].map(s => (
              <div className="control-row" key={s.id} onClick={() => setSelected(s)}>
                <div className="control-main">
                  <span className="control-cat">{s.category}</span>
                  <span className="control-meta">{s.employeeName} · {s.shift} · {new Date(s.submittedAt).toLocaleTimeString("es-AR", { hour: "2-digit", minute: "2-digit" })}</span>
                </div>
                <ChevronRight size={16} color="#8AAFA9" />
              </div>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
}

/* ---------------------------------------------------------------- */
/* App principal                                                     */
/* ---------------------------------------------------------------- */

function MainApp({
  session, onLogout, users, setUsers, items, setItems, assignments, setAssignments,
  categories, setCategories, suppliers, setSuppliers, locations, setLocations, log, addLogBatch, submissions, upsertSubmission, shiftLimits, setShiftLimits,
  overrides, upsertOverride, removeOverride,
}) {
  const isAdmin = session.role === "admin";
  const [tab, setTab] = useState(isAdmin ? "hoy" : "turno");
  const lowCount = items.filter(i => itemTotalStock(i, locations) < Number(i.minStock)).length;
  const unassignedCount = categories.filter(cat => {
    if (!items.some(i => itemCategories(i).includes(cat))) return false;
    return !assignments.some(a => (a.categories || []).includes(cat) && a.days.length > 0);
  }).length;

  const tabs = isAdmin
    ? [
      { id: "hoy", label: "Hoy", icon: ListChecks },
      { id: "pendientes", label: "Pendientes", icon: AlertTriangle, badge: lowCount },
      { id: "insumos", label: "Insumos", icon: Package },
      { id: "empleados", label: "Empleados", icon: Users },
      { id: "asignaciones", label: "Turnos", icon: CalendarDays, badge: unassignedCount },
      { id: "historial", label: "Historial", icon: Clock },
    ]
    : [
      { id: "turno", label: "Mi turno", icon: ClipboardCheck },
      { id: "pendientes", label: "Pendientes", icon: AlertTriangle, badge: lowCount },
    ];

  return (
    <div className="stockapp">
      <GlobalStyles />
      <div className="sa-shell">
        <div className="sa-header">
          <div className="brand">
            <img src={LOGO_SRC} alt="Ágape" style={{ height: 30, width: "auto" }} />
            <div className="brand-text">
              <div className="who" style={{ marginTop: 1 }}>{session.name} · {isAdmin ? "Admin" : "Empleado"}</div>
            </div>
          </div>
          <button className="sa-icon-btn" onClick={onLogout} title="Salir"><LogOut size={16} /></button>
        </div>

        {lowCount > 0 && tab !== "pendientes" && (
          <div className="sa-alert-banner" onClick={() => setTab("pendientes")}>
            <AlertTriangle size={16} /> {lowCount} insumo{lowCount > 1 ? "s" : ""} por debajo del mínimo — ver pendientes
          </div>
        )}

        <div className="sa-content">
          {tab === "turno" && (
            <MyShift
              session={session} assignments={assignments} overrides={overrides} items={items} setItems={setItems}
              locations={locations}
              addLogBatch={addLogBatch} submissions={submissions} upsertSubmission={upsertSubmission}
              shiftLimits={shiftLimits}
            />
          )}
          {tab === "hoy" && isAdmin && (
            <TodayOverview
              assignments={assignments} overrides={overrides} upsertOverride={upsertOverride} removeOverride={removeOverride}
              users={users} submissions={submissions} shiftLimits={shiftLimits}
            />
          )}
          {tab === "pendientes" && <Pendientes items={items} locations={locations} />}
          {tab === "insumos" && isAdmin && <ItemsAdmin items={items} setItems={setItems} categories={categories} setCategories={setCategories} suppliers={suppliers} setSuppliers={setSuppliers} locations={locations} setLocations={setLocations} />}
          {tab === "empleados" && isAdmin && <EmployeesAdmin users={users} setUsers={setUsers} session={session} />}
          {tab === "asignaciones" && isAdmin && (
            <AssignmentsAdmin
              assignments={assignments} setAssignments={setAssignments} users={users} items={items}
              categories={categories} shiftLimits={shiftLimits} setShiftLimits={setShiftLimits}
            />
          )}
          {tab === "historial" && isAdmin && <History submissions={submissions} items={items} locations={locations} />}
        </div>

        <div className="sa-tabbar">
          {tabs.map(t => (
            <button key={t.id} className={"sa-tab" + (tab === t.id ? " active" : "")} onClick={() => setTab(t.id)}>
              {!!t.badge && <span className="sa-tab-badge">{t.badge}</span>}
              <t.icon size={17} />
              {t.label}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

/* ---------------------------------------------------------------- */
/* Root: carga y persistencia                                        */
