export default function App() {
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState(false);
  const [conflictNotice, setConflictNotice] = useState(null);
  const baselineRef = useRef({}); // último valor crudo (string) conocido de cada key en la base
  const [users, setUsersState] = useState([]);
  const [items, setItemsState] = useState([]);
  const [assignments, setAssignmentsState] = useState([]);
  const [categories, setCategoriesState] = useState([]);
  const [suppliers, setSuppliersState] = useState([]);
  const [locations, setLocationsState] = useState(DEFAULT_LOCATIONS);
  const [log, setLogState] = useState([]);
  const [submissions, setSubmissionsState] = useState([]);
  const [overrides, setOverridesState] = useState([]);
  const [shiftLimits, setShiftLimitsState] = useState(DEFAULT_SHIFT_LIMITS);
  const [session, setSession] = useState(null);

  const loadAll = useCallback(async () => {
    setLoading(true);
    setLoadError(false);

    // Cada clave se pide por separado. Si CUALQUIERA falla (corte de red, Supabase
    // caído, etc.) NO seguimos: no queremos que un error de conexión se confunda
    // con "no hay datos todavía" y termine pisando usuarios/insumos reales con los
    // valores por defecto. Solo seedeamos admin/categorías si la lectura funcionó
    // bien y el valor vino genuinamente vacío (primera vez que se usa la app).
    const keys = {
      u: "test-app:users", it: "test-app:items", as: "test-app:assignments", cats: "test-app:categories",
      sups: "test-app:suppliers", locs: "test-app:locations", lg: "test-app:stock-log", subs: "test-app:submissions",
      ovs: "test-app:overrides", limits: "test-app:shift-limits",
    };
    const result = {};
    const rawResult = {};
    for (const [name, key] of Object.entries(keys)) {
      try {
        const r = await window.storage.get(key, true);
        result[name] = r ? JSON.parse(r.value) : null;
        rawResult[name] = r ? r.value : null;
      } catch (e) {
        setLoadError(true);
        setLoading(false);
        return; // abortamos sin tocar nada guardado
      }
    }
    baselineRef.current = { ...baselineRef.current, ...Object.fromEntries(
      Object.entries(keys).map(([name, key]) => [key, rawResult[name]])
    )};

    let { u, it, as, cats, sups, locs, lg, subs, ovs, limits } = result;
    u = u || []; it = it || []; as = as || []; cats = cats || [];
    sups = sups || []; lg = lg || []; subs = subs || []; ovs = ovs || [];

    if (u.length === 0) {
      u = [{ id: "admin_default", name: "Admin", pin: "1234", role: "admin" }];
      const raw = JSON.stringify(u);
      try { await window.storage.set("test-app:users", raw, true); baselineRef.current["test-app:users"] = raw; } catch (e) { }
    }
    if (!cats || cats.length === 0) {
      cats = DEFAULT_CATEGORIES.slice();
      const raw = JSON.stringify(cats);
      try { await window.storage.set("test-app:categories", raw, true); baselineRef.current["test-app:categories"] = raw; } catch (e) { }
    }
    if (!limits) {
      limits = { ...DEFAULT_SHIFT_LIMITS };
      const raw = JSON.stringify(limits);
      try { await window.storage.set("test-app:shift-limits", raw, true); baselineRef.current["test-app:shift-limits"] = raw; } catch (e) { }
    }
    if (!locs || locs.length === 0) {
      locs = DEFAULT_LOCATIONS.map(l => ({ ...l }));
      const raw = JSON.stringify(locs);
      try { await window.storage.set("test-app:locations", raw, true); baselineRef.current["test-app:locations"] = raw; } catch (e) { }
    }

    // Migración: insumos guardados antes de que existiera el soporte para
    // varias categorías o para stock por ubicación todavía tienen los campos
    // viejos `category` (singular) y/o `currentStock` (un solo número). Los
    // pasamos a `categories` (array) y `stock` (objeto por ubicación) para
    // que convivan bien con los insumos nuevos, sin perder lo que ya tenían
    // cargado (todo el stock viejo queda en la primera ubicación).
    let itemsMigrated = false;
    it = it.map(item => {
      let next = item;
      if (!Array.isArray(item.categories)) {
        itemsMigrated = true;
        const { category, ...rest } = next;
        next = { ...rest, categories: category ? [category] : [] };
      }
      if (!next.stock || typeof next.stock !== "object") {
        itemsMigrated = true;
        const { currentStock, ...rest } = next;
        const stock = {};
        locs.forEach((l, idx) => { stock[l.id] = idx === 0 ? (Number(currentStock) || 0) : 0; });
        next = { ...rest, stock };
      }
      return next;
    });
    if (itemsMigrated && it.length > 0) {
      const raw = JSON.stringify(it);
      try { await window.storage.set("test-app:items", raw, true); baselineRef.current["test-app:items"] = raw; } catch (e) { }
    }

    setUsersState(u); setItemsState(it); setAssignmentsState(as); setCategoriesState(cats); setSuppliersState(sups); setLocationsState(locs);
    setLogState(lg); setSubmissionsState(subs); setOverridesState(ovs); setShiftLimitsState(limits);
    setLoading(false);
  }, []);

  useEffect(() => { loadAll(); }, [loadAll]);

  useEffect(() => {
    if (!conflictNotice) return;
    const t = setTimeout(() => setConflictNotice(null), 6000);
    return () => clearTimeout(t);
  }, [conflictNotice]);

  // Guarda `next` bajo `key` solo si nadie más lo cambió desde la última vez que lo
  // leímos en este celular. Si detecta que otra sesión (otro admin, otro celular)
  // ya guardó algo distinto mientras tanto, NO lo pisa: recarga lo más reciente,
  // avisa, y el cambio que se intentaba hacer se pierde (hay que reintentarlo
  // a mano, ya viendo los datos al día).
  async function saveKey(key, next, applyLocal) {
    const nextRaw = JSON.stringify(next);
    let current;
    try {
      current = await window.storage.get(key, true);
    } catch (e) {
      setConflictNotice("No se pudo guardar: revisá tu conexión e intentá de nuevo.");
      return false;
    }
    const currentRaw = current ? current.value : null;
    const baseline = baselineRef.current[key] ?? null;
    if (currentRaw !== baseline) {
      baselineRef.current[key] = currentRaw;
      applyLocal(currentRaw ? JSON.parse(currentRaw) : next);
      setConflictNotice("Alguien más actualizó esto justo ahora, desde otro celular. Se cargó la versión más reciente — tu cambio no se guardó, probalo de nuevo.");
      return false;
    }
    try {
      await window.storage.set(key, nextRaw, true);
    } catch (e) {
      setConflictNotice("No se pudo guardar: revisá tu conexión e intentá de nuevo.");
      return false;
    }
    baselineRef.current[key] = nextRaw;
    applyLocal(next);
    return true;
  }

  async function setUsers(next) { await saveKey("test-app:users", next, setUsersState); }

  // Casos "aditivos": TODOS los empleados los tocan cada vez que envían un
  // control (cada uno solo actualiza los insumos de su categoría, o agrega su
  // propia entrada de log/submission), y el admin también los edita agregando
  // categorías/proveedores nuevos al importar o crear insumos. Si comparásemos
  // contra una foto vieja como en saveKey(), el envío de un empleado en la
  // categoría "Bebidas" y el de otro en "Panadería" a la vez (o dos altas de
  // categoría casi simultáneas) se verían como un "conflicto" entre sí y uno
  // de los dos perdería su actualización — aunque no toquen lo mismo. Por eso
  // acá siempre releemos la versión más fresca de la base justo antes de
  // aplicar el cambio, así cada actualización se arma sobre lo último que
  // hay, sin pisar lo que cargó otra persona ni disparar un aviso de
  // conflicto que no es real.
  async function mergeKey(key, updaterFn, applyLocal) {
    let freshRaw;
    try {
      const r = await window.storage.get(key, true);
      freshRaw = r ? r.value : null;
    } catch (e) {
      setConflictNotice("No se pudo guardar: revisá tu conexión e intentá de nuevo.");
      return false;
    }
    const fresh = freshRaw ? JSON.parse(freshRaw) : [];
    const next = updaterFn(fresh);
    const nextRaw = JSON.stringify(next);
    try {
      await window.storage.set(key, nextRaw, true);
    } catch (e) {
      setConflictNotice("No se pudo guardar: revisá tu conexión e intentá de nuevo.");
      return false;
    }
    baselineRef.current[key] = nextRaw;
    applyLocal(next);
    return true;
  }

  function asUpdater(nextOrUpdater) {
    return typeof nextOrUpdater === "function" ? nextOrUpdater : () => nextOrUpdater;
  }

  async function setItems(nextOrUpdater) { await mergeKey("test-app:items", asUpdater(nextOrUpdater), setItemsState); }
  async function setCategories(nextOrUpdater) { await mergeKey("test-app:categories", asUpdater(nextOrUpdater), setCategoriesState); }
  async function setSuppliers(nextOrUpdater) { await mergeKey("test-app:suppliers", asUpdater(nextOrUpdater), setSuppliersState); }
  async function setLocations(nextOrUpdater) { await mergeKey("test-app:locations", asUpdater(nextOrUpdater), setLocationsState); }

  async function setAssignments(next) { await saveKey("test-app:assignments", next, setAssignmentsState); }
  async function setShiftLimits(next) { await saveKey("test-app:shift-limits", next, setShiftLimitsState); }
  async function addLogBatch(entries) {
    const withIds = entries.map(e => ({ id: uid("log"), ...e }));
    await mergeKey("test-app:stock-log", freshLog => {
      let next = [...withIds, ...freshLog];
      if (next.length > 300) next = next.slice(0, 300);
      return next;
    }, setLogState);
  }
  async function upsertSubmission(entry) {
    await mergeKey("test-app:submissions", freshSubs => {
      const idx = freshSubs.findIndex(s => s.id === entry.id);
      let next;
      if (idx >= 0) { next = freshSubs.slice(); next[idx] = entry; } else { next = [entry, ...freshSubs]; }
      if (next.length > 500) next = next.slice(0, 500);
      return next;
    }, setSubmissionsState);
  }
  async function upsertOverride(entry) {
    const idx = overrides.findIndex(o => o.id === entry.id);
    let next;
    if (idx >= 0) { next = overrides.slice(); next[idx] = entry; } else { next = [entry, ...overrides]; }
    if (next.length > 500) next = next.slice(0, 500);
    await saveKey("test-app:overrides", next, setOverridesState);
  }
  async function removeOverride(id) {
    const next = overrides.filter(o => o.id !== id);
    await saveKey("test-app:overrides", next, setOverridesState);
  }

  if (loading) return <LoadingScreen />;
  if (loadError) return <ErrorScreen onRetry={loadAll} />;
  if (!session) return <Login users={users} onLogin={setSession} />;

  return (
    <>
      <MainApp
        session={session}
        onLogout={() => setSession(null)}
        users={users} setUsers={setUsers}
        items={items} setItems={setItems}
        assignments={assignments} setAssignments={setAssignments}
        categories={categories} setCategories={setCategories}
        suppliers={suppliers} setSuppliers={setSuppliers}
        locations={locations} setLocations={setLocations}
        log={log} addLogBatch={addLogBatch}
        submissions={submissions} upsertSubmission={upsertSubmission}
        overrides={overrides} upsertOverride={upsertOverride} removeOverride={removeOverride}
        shiftLimits={shiftLimits} setShiftLimits={setShiftLimits}
      />
      {conflictNotice && (
        <div className="conflict-toast" onClick={() => setConflictNotice(null)}>
          <AlertTriangle size={16} />
          <span>{conflictNotice}</span>
        </div>
      )}
    </>
  );
}
